  budgets?: AcceleratorBudget[]
  /** Distribution is this leaf's default split policy, overridable per budget entry. Unset means the operator-level default from the quota config applies; absent that too, the node reports Degraded rather than guessing. */
  distribution?: AcceleratorQuotaDistribution
